## R-side matrix interface utilities

# -- Convert values to canonical R matrix form -------------------------
## CVXPY equivalent: intf.convert() / DEFAULT_INTF.const_to_matrix()

#' Convert a value to a numeric matrix or sparse matrix
#'
#' Normalizes R values so the rest of CVXR can assume a consistent type.
#' Scalars -> 1x1 matrix, vectors -> column matrix, logical -> numeric.
#' Sparse matrices are kept sparse.
#'
#' @param val A numeric scalar, vector, matrix, or Matrix object
#' @returns A matrix or dgCMatrix
#' @keywords internal
intf_convert <- function(val) {
  if (inherits(val, "sparseVector")) {
    ## Convert sparseVector to sparse column matrix
    n <- length(val)
    idx <- val@i
    vals <- val@x
    return(Matrix::sparseMatrix(i = idx, j = rep(1L, length(idx)),
                                x = vals, dims = c(n, 1L)))
  }
  if (inherits(val, "sparseMatrix")) {
    ## Keep sparse matrices sparse, but ensure numeric (not logical)
    if (is.logical(val@x)) {
      val <- as(val, "dgCMatrix")
    }
    return(val)
  }
  if (is.logical(val)) {
    val <- as.numeric(val)
  }
  ## Complex values: preserve complex type (do NOT coerce to double)
  if (is.complex(val)) {
    if (!is.matrix(val)) {
      if (length(val) == 1L) {
        val <- matrix(val, 1L, 1L)
      } else {
        val <- matrix(val, ncol = 1L)
      }
    }
    return(val)
  }
  if (is.numeric(val) && !is.matrix(val)) {
    if (length(val) == 1L) {
      val <- matrix(val, 1L, 1L)
    } else {
      ## Vector -> column matrix (Fortran-order, matching CVXPY)
      val <- matrix(val, ncol = 1L)
    }
  }
  if (is.matrix(val)) {
    if (!is.numeric(val)) {
      storage.mode(val) <- "double"
    }
    return(val)
  }
  if (inherits(val, "Matrix")) {
    return(as.matrix(val))
  }
  cli_abort("Cannot convert object of class {.cls {class(val)}} to a CVXR matrix.")
}

# -- Shape of a value --------------------------------------------------
## CVXPY equivalent: intf.shape()

#' Get the shape of a value as an integer vector c(nrow, ncol)
#' @param val A numeric scalar, vector, matrix, or Matrix object
#' @returns Integer vector of length 2
#' @keywords internal
intf_shape <- function(val) {
  if (is.matrix(val) || inherits(val, "Matrix")) {
    return(c(nrow(val), ncol(val)))
  }
  if (length(val) == 1L) {
    return(c(1L, 1L))
  }
  ## Vector
  c(length(val), 1L)
}

# -- Sign of a value --------------------------------------------------
## CVXPY equivalent: intf.sign()

#' Determine the sign of a numeric value
#' @param val A numeric matrix or sparse matrix
#' @returns List with \code{is_nonneg} (logical) and \code{is_nonpos} (logical)
#' @keywords internal
intf_sign <- function(val) {
  ## Handle empty values (0-element)
  if (length(val) == 0L) {
    return(list(is_nonneg = TRUE, is_nonpos = TRUE))
  }
  ## Complex values have no sign ordering
  ## CVXPY SOURCE: constant.py _compute_attr() sets nonneg=nonpos=False for complex
  if (is.complex(val)) {
    return(list(is_nonneg = FALSE, is_nonpos = FALSE))
  }
  if (inherits(val, "sparseMatrix")) {
    ## Pattern matrices (ngCMatrix etc.) have no @x slot -- treat as all zeros
    if (!.hasSlot(val, "x") || length(val@x) == 0L) {
      return(list(is_nonneg = TRUE, is_nonpos = TRUE))
    }
    vals <- val@x
  } else {
    vals <- as.numeric(val)
  }
  ## NaN -> treat as unknown sign (neither nonneg nor nonpos)
  if (anyNA(vals)) {
    return(list(is_nonneg = FALSE, is_nonpos = FALSE))
  }
  mx <- max(vals)
  mn <- min(vals)
  list(is_nonneg = (mn >= 0), is_nonpos = (mx <= 0))
}

# -- Is sparse? --------------------------------------------------------
## CVXPY equivalent: intf.is_sparse()

#' Check if a value is a sparse matrix
#' @param val A value
#' @returns Logical
#' @keywords internal
intf_is_sparse <- function(val) {
  inherits(val, "sparseMatrix")
}

# -- Hermitian / symmetric check ---------------------------------------
## CVXPY SOURCE: interface/matrix_utilities.py:276-299 is_hermitian (CVXPY 1.9.3)
##
## Tolerance is numpy's `np.allclose` (rtol 1e-5, atol 1e-8, FALSE on NaN),
## through `.np_allclose` (zzz_R_specific/utility.R).  Through CVXR 1.9.2.9154
## these tests used `all.equal` / `isSymmetric` at 1e-10, a MEAN relative
## difference that rejected what CVXPY accepts (an off-diagonal pair differing
## by 1e-7 made quad_form abort), accepted what CVXPY rejects (a 1e12 pair off
## by 1e-3 was skew-symmetric), and called a NaN matrix symmetric so that
## is_psd crashed in eigen() (claims audit C0487, decision 22, 1.9.2.9155).
##
## Dense matrices are compared entry by entry.  Before transposing, rows 1, 2,
## n-1 and n are compared with the matching columns, as base R's
## isSymmetric.matrix does: those comparisons are a subset of the full test,
## so the answer is unchanged, and an asymmetric 1000 x 1000 matrix is
## rejected in microseconds instead of after a 16 MB transpose.

#' Check if a matrix is symmetric (and Hermitian for real case)
#' @param val A numeric matrix or sparse matrix
#' @returns List with \code{is_symmetric} (logical) and \code{is_hermitian} (logical)
#' @keywords internal
intf_is_hermitian <- function(val) {
  if (is.complex(val)) {
    ## "symmetric" always means "real symmetric" in CVXPY (the comment at
    ## matrix_utilities.py:281-287), so is_symmetric is FALSE for complex.
    is_symm <- FALSE
    if (inherits(val, "sparseMatrix")) {
      is_herm <- intf_is_sparse_symmetric(val, complex = TRUE)
    } else {
      is_herm <- .dense_allclose_transpose(val, Conj)
    }
    return(list(is_symmetric = is_symm, is_hermitian = is_herm))
  }
  if (inherits(val, "sparseMatrix")) {
    is_symm <- intf_is_sparse_symmetric(val, complex = FALSE)
  } else {
    is_symm <- .dense_allclose_transpose(val, identity)
  }
  list(is_symmetric = is_symm, is_hermitian = is_symm)
}

## `np.allclose(val, cj(val.T))` for a dense matrix, with the row/column
## pre-check described above.  `cj` is Conj for the Hermitian test and
## identity for the symmetric one.
.dense_allclose_transpose <- function(val, cj) {
  if (inherits(val, "Matrix")) val <- as.matrix(val)
  n <- nrow(val)
  if (n > 1L) {
    for (i in unique(c(1L, 2L, n - 1L, n))) {
      if (!.np_allclose(val[i, ], cj(val[, i]))) return(FALSE)
    }
  }
  .np_allclose(val, cj(t(val)))
}

## CVXPY SOURCE: interface/matrix_utilities.py:315-366 is_sparse_symmetric
##
## Structure first, values second: after summing duplicates and dropping
## explicit zeros, the strict lower and strict upper triangles must hold the
## same positions (mirrored), and then the paired values must be allclose
## (conjugated for the Hermitian test).  A stored 1e-9 facing an absent entry
## is therefore NOT symmetric here even though the dense test would accept it,
## exactly as upstream.  The complex branch is unreachable in R today (Matrix
## has no complex sparse class) and is kept for isomorphism.
##
## Same test, no sorting.  Upstream lexsorts the two triangles and compares
## them.  A canonical compressed-column matrix (row indices increasing within
## each column, no duplicates, no explicit zeros) is a sorted position list
## already, and so is its transpose, so "the lower positions mirror the upper
## positions" is `identical(pattern(m), pattern(t(m)))`, and entry k of
## `t(m)@x` is the mirror of entry k of `m@x`.  The value comparison is
## restricted to the strict lower triangle so that the `rtol * |b|` side is
## the upper mirror, as in upstream's `np.allclose(vl, vu)`.  Measured on a
## 1000 x 1000 matrix with 2e4 nonzeros: the lexsort form took 411 us / 1.8 MB
## against 144 us for the old Matrix::isSymmetric; this form is in the table
## under "Decision 22" in notes/audit/claims_audit_item1.md.

#' Check if a sparse matrix is symmetric (or Hermitian)
#' @param m A square sparse matrix
#' @param complex If \code{TRUE}, test \code{m == Conj(t(m))}
#' @returns Logical scalar
#' @keywords internal
intf_is_sparse_symmetric <- function(m, complex = FALSE) {
  if (nrow(m) != ncol(m)) cli_abort("m must be a square matrix")
  m <- .csc_canonical(m)
  mt <- Matrix::t(m)
  ## Entry (i, j) in the lower triangle must mirror entry (j, i) in the upper.
  if (!(identical(m@p, mt@p) && identical(m@i, mt@i))) return(FALSE)
  lower <- m@i > rep.int(seq_len(ncol(m)) - 1L, diff(m@p))   # strict lower triangle
  vl <- m@x[lower]
  vu <- mt@x[lower]
  if (complex) .np_allclose(vl, Conj(vu)) else .np_allclose(vl, vu)
}

## `sp.coo_array(m); m.sum_duplicates(); m.eliminate_zeros()` for a Matrix
## object: a general dgCMatrix with duplicates summed and explicit zeros
## dropped.  Symmetric and diagonal storage classes keep one triangle only,
## so the matrix is expanded to a general one first; a dgCMatrix is already
## canonical up to explicit zeros.
.csc_canonical <- function(m) {
  if (!inherits(m, "dgCMatrix")) {
    m <- as(as(as(m, "dMatrix"), "generalMatrix"), "CsparseMatrix")   # sums duplicates
  }
  if (any(m@x == 0)) m <- Matrix::drop0(m)
  m
}

# -- Skew-symmetric check ---------------------------------------------
## CVXPY SOURCE: interface/matrix_utilities.py:302-312 is_skew_symmetric
##
## `np.allclose(constant + constant.T, 0.0)`: the reference is 0, so only
## atol = 1e-8 applies.  Same row/column pre-check as the symmetric test.

#' Check if a matrix is skew-symmetric (A + A^T == 0)
#' @param val A numeric matrix or sparse matrix
#' @returns Logical scalar
#' @keywords internal
intf_is_skew_symmetric <- function(val) {
  ## Non-square: error (matches CVXPY)
  if (nrow(val) != ncol(val)) {
    cli_abort("Skew-symmetry requires a square matrix.")
  }
  ## Complex matrices: skew-symmetric not defined in CVXPY (returns False)
  if (is.complex(val)) return(FALSE)
  if (inherits(val, "sparseMatrix")) return(intf_is_sparse_skew_symmetric(val))
  if (inherits(val, "Matrix")) val <- as.matrix(val)
  n <- nrow(val)
  if (n > 1L) {
    for (i in unique(c(1L, 2L, n - 1L, n))) {
      if (!.np_allclose(val[i, ] + val[, i], 0)) return(FALSE)
    }
  }
  .np_allclose(val + t(val), 0)
}

## CVXPY SOURCE: interface/matrix_utilities.py:369-413 is_sparse_skew_symmetric
##
## As is_sparse_symmetric, with the diagonal included on both sides (a
## diagonal entry mirrors itself, so it must be allclose to 0 after doubling)
## and the paired values summed against 0.  Same pattern-of-the-transpose
## form as above.

#' Check if a real sparse matrix satisfies A + t(A) == 0
#' @param A A square sparse matrix
#' @returns Logical scalar
#' @keywords internal
intf_is_sparse_skew_symmetric <- function(A) {
  if (nrow(A) != ncol(A)) cli_abort("m must be a square matrix")
  A <- .csc_canonical(A)
  At <- Matrix::t(A)
  ## Entry (i, j) with i >= j must mirror entry (j, i) with j <= i.
  if (!(identical(A@p, At@p) && identical(A@i, At@i))) return(FALSE)
  lower <- A@i >= rep.int(seq_len(ncol(A)) - 1L, diff(A@p))   # lower triangle with diagonal
  .np_allclose(A@x[lower] + At@x[lower], 0)
}

# -- PSD check via eigenvalues -----------------------------------------
## CVXPY equivalent: utilities/linalg.py::is_psd_within_tol

#' Check if a symmetric matrix is PSD within tolerance
#' @param val A symmetric numeric matrix
#' @param tol Eigenvalue tolerance
#' @returns Logical
#' @keywords internal
intf_is_psd <- function(val, tol = EIGVAL_TOL) {
  ev <- .eigvalsh(val, only_values = TRUE)$values
  all(ev >= -tol)
}
